// 各种实时通信方案的代码示例

// ========== 1. 短轮询 ==========
function shortPolling() {
    setInterval(async () => {
        const resp = await fetch('/api/messages?since=' + lastId);
        const data = await resp.json();
        if (data.length > 0) {
            data.forEach(msg => displayMessage(msg));
            lastId = data[data.length - 1].id;
        }
    }, 3000);  // 每3秒轮询
}

// ========== 2. 长轮询 ==========
async function longPolling() {
    while (true) {
        try {
            const resp = await fetch('/api/messages/subscribe?since=' + lastId, {
                signal: AbortSignal.timeout(30000)  // 30秒超时
            });
            const data = await resp.json();
            if (data.length > 0) {
                data.forEach(msg => displayMessage(msg));
                lastId = data[data.length - 1].id;
            }
        } catch (e) {
            await new Promise(r => setTimeout(r, 1000));  // 错误后等待1秒
        }
        // 立即发起下一次请求
    }
}

// ========== 3. SSE (Server-Sent Events) ==========
function sseDemo() {
    const source = new EventSource('/api/events');

    // 监听默认消息
    source.onmessage = function(event) {
        const data = JSON.parse(event.data);
        displayMessage(data);
    };

    // 监听自定义事件
    source.addEventListener('notification', function(event) {
        const data = JSON.parse(event.data);
        showNotification(data);
    });

    // 错误处理和自动重连
    source.onerror = function(event) {
        if (source.readyState === EventSource.CLOSED) {
            console.log('连接已关闭');
        } else {
            console.log('连接断开，自动重连中...');
            // EventSource会自动重连
        }
    };
}

// ========== 4. WebSocket ==========
function websocketDemo() {
    const ws = new WebSocket('wss://example.com/ws');

    ws.onopen = () => ws.send(JSON.stringify({ type: 'subscribe' }));

    ws.onmessage = (event) => {
        const data = JSON.parse(event.data);
        displayMessage(data);
    };

    ws.onclose = (event) => {
        if (!event.wasClean) {
            setTimeout(() => websocketDemo(), 3000);  // 自动重连
        }
    };
}

// ========== 服务端SSE示例(Express) ==========
app.get('/api/events', (req, res) => {
    res.setHeader('Content-Type', 'text/event-stream');
    res.setHeader('Cache-Control', 'no-cache');
    res.setHeader('Connection', 'keep-alive');

    const sendEvent = (data) => {
        res.write(`data: ${JSON.stringify(data)}\n\n`);
    };

    // 发送自定义事件
    const sendNotification = (data) => {
        res.write(`event: notification\n`);
        res.write(`data: ${JSON.stringify(data)}\n\n`);
    };

    // 定期发送心跳
    const heartbeat = setInterval(() => {
        res.write(':heartbeat\n\n');
    }, 30000);

    req.on('close', () => clearInterval(heartbeat));
});
